def dihedral(points):
 out=[]
 for refl in (False,True):
  for k in range(4):
   ps=[]
   for r,c in points:
    if refl: c=-c
    for _ in range(k): r,c=c,-r
    ps.append((r,c))
   mr=min(r for r,c in ps); mc=min(c for r,c in ps)
   ps=tuple(sorted((r-mr,c-mc) for r,c in ps))
   if ps not in out: out.append(ps)
 return out
